473	    for (const dependency of nodeDependencies.get(node)) {
474	      adjacency.get(dependency).push(id);
475	    }
476	  }
477	  const color = new Map([...nodes.keys()].map(id => [id, 'white']));
478	  const stack = [];
479	  const visit = id => {
480	    color.set(id, 'gray');
481	    stack.push(id);
482	    for (const target of adjacency.get(id)) {
483	      if (color.get(target) === 'gray') {
484	        const chain = [...stack.slice(stack.indexOf(target)), target];
485	        throw new Error(`cycle is present: ${chain.join(' -> ')}`);
486	      }
487	      if (color.get(target) === 'white') visit(target);
488	    }
489	    stack.pop();
490	    color.set(id, 'black');
491	  };
