1	import test from 'node:test';
2	import assert from 'node:assert/strict';
3	import { executeWorkflow, executeWorkflowAsync, validateWorkflow } from '../src/engine.js';
4	
5	// Workflow: start -> risk-check (action) -> check (condition) -> pass/fail.
6	function outputConditionWorkflow(condition, { actionProps = {}, sync = false } = {}) {
7	  return {
8	    id: 'out-cond',
9	    entry: 'start',
10	    nodes: [
11	      { id: 'start', type: 'trigger', next: 'risk-check' },
12	      {
13	        id: 'risk-check', type: 'action',
14	        ...(sync ? { message: 'hello' } : { operation: 'risk' }),
15	        ...actionProps,
16	        next: 'check',
17	      },
18	      { id: 'check', type: 'condition', condition, then: 'pass', else: 'fail' },
19	      { id: 'pass', type: 'end', result: 'passed' },
20	      { id: 'fail', type: 'end', result: 'failed' },
21	    ],
22	  };
23	}
24	
25	const branchOf = async (condition, operations, input = {}) => {
26	  const result = await executeWorkflowAsync(outputConditionWorkflow(condition), input, operations);
27	  return result.result;
28	};
29	
30	test('routes a condition by an action output path without writing it back to input', async () => {
31	  const condition = {
32	    outputField: { nodeId: 'risk-check', path: 'risk.score' },
33	    operator: 'gte', valueField: 'threshold',
34	  };
35	  const high = await executeWorkflowAsync(
36	    outputConditionWorkflow(condition), { threshold: 80 }, { risk: () => ({ risk: { score: 80 } }) });
37	  assert.equal(high.result, 'passed');
38	  // The action output is never written back to the input.
39	  assert.deepEqual(high.context.input, { threshold: 80 });
40	
41	  const low = await executeWorkflowAsync(
42	    outputConditionWorkflow(condition), { threshold: 90 }, { risk: () => ({ risk: { score: 80 } }) });
43	  assert.equal(low.result, 'failed');
44	});
45	
46	test('outputField with no path reads the whole return value', async () => {
47	  assert.equal(
48	    await branchOf({ outputField: { nodeId: 'risk-check' }, operator: 'eq', value: 'ok' },
49	      { risk: () => 'ok' }),
50	    'passed');
51	  assert.equal(
52	    await branchOf({ outputField: { nodeId: 'risk-check' }, operator: 'eq', value: 'ok' },
53	      { risk: () => 'nope' }),
54	    'failed');
55	});
56	
57	test('valueOutputField compares two action outputs', async () => {
58	  const workflow = {
59	    id: 'two-outputs', entry: 'start',
60	    nodes: [
61	      { id: 'start', type: 'trigger', next: 'risk-check' },
62	      { id: 'risk-check', type: 'action', operation: 'risk', next: 'limit-src' },
63	      { id: 'limit-src', type: 'action', operation: 'limit', next: 'check' },
64	      { id: 'check', type: 'condition', condition: {
65	        outputField: { nodeId: 'risk-check', path: 'risk.score' },
66	        operator: 'gte',
67	        valueOutputField: { nodeId: 'limit-src', path: 'max' },
68	      }, then: 'pass', else: 'fail' },
69	      { id: 'pass', type: 'end', result: 'passed' },
70	      { id: 'fail', type: 'end', result: 'failed' },
71	    ],
72	  };
73	  const run = async (riskValue, limitValue) =>
74	    (await executeWorkflowAsync(workflow, {}, {
75	      risk: () => ({ risk: { score: riskValue } }),
76	      limit: () => ({ max: limitValue }),
77	    })).result;
78	  assert.equal(await run(80, 80), 'passed');
79	  assert.equal(await run(70, 80), 'failed');
80	  // eq is never coerced: '80' !== 80.
81	  const eqWorkflow = structuredClone(workflow);
82	  eqWorkflow.nodes.find(n => n.type === 'condition').condition.operator = 'eq';
83	  assert.equal(
84	    (await executeWorkflowAsync(eqWorkflow, {}, {
85	      risk: () => ({ risk: { score: '80' } }),
86	      limit: () => ({ max: 80 }),
87	    })).result,
88	    'failed');
89	});
90	
91	test('new and old references can be mixed on either side', async () => {
92	  // field (input) vs valueOutputField (action output)
93	  assert.equal(
94	    await branchOf({ field: 'score', operator: 'gte', valueOutputField: { nodeId: 'risk-check', path: 'limit' } },
95	      { risk: () => ({ limit: 5 }) }, { score: 6 }),
96	    'passed');
97	  assert.equal(
98	    await branchOf({ field: 'score', operator: 'gte', valueOutputField: { nodeId: 'risk-check', path: 'limit' } },
99	      { risk: () => ({ limit: 5 }) }, { score: 4 }),
100	    'failed');
101	  // outputField (action output) vs valueField (input)
102	  assert.equal(
103	    await branchOf({ outputField: { nodeId: 'risk-check', path: 'score' }, operator: 'lte', valueField: 'cap' },
104	      { risk: () => ({ score: 3 }) }, { cap: 5 }),
105	    'passed');
106	});
107	
108	test('exists with outputField judges presence of the action output', async () => {
109	  const present = path => branchOf(
110	    { outputField: { nodeId: 'risk-check', ...(path ? { path } : {}) }, operator: 'exists' },
111	    { risk: () => ({ risk: { score: 80 } }) });
112	  assert.equal(await present('risk.score'), 'passed');
