        { id: 'start', type: 'trigger', next: '__proto__' },
        { id: '__proto__', type: 'action', operation: 'score', next: 'other' },
        { id: 'other', type: 'action', operation: 'cap', next: 'check' },
        { id: 'check', type: 'condition', condition, then: 'pass', else: 'fail' },
